#!/bin/sh
# User documentation in docs/wiki (published to the GitHub wiki by
# scripts/publish-wiki.sh), and the same documentation for AI agents in
# docs/agents.
#
#   scripts/docs.sh           # regenerate the generated files
#   scripts/docs.sh --check   # fail if one is out of date or a link is broken
#                             # (`just ci`)
#
# Generated:
#   docs/wiki/CLI-Reference.md               from `compost … --help`, i.e. the
#                                            clap doc comments of src/cli
#   docs/wiki/Bundled-Images.md              from `compost images --markdown`
#   docs/agents/llms.txt                     docs/agents/llms-index.md with links
#                                            to the wiki
#   docs/agents/llms-full.txt                every page of docs/wiki in one file
#   docs/agents/skills/compost/references/   copies of the pages of docs/wiki
# docs/agents/llms-index.md and docs/agents/skills/compost/SKILL.md are written
# by hand.
set -eu

pages=docs/wiki
out=$pages/CLI-Reference.md
images_out=$pages/Bundled-Images.md
agents=docs/agents
references=$agents/skills/compost/references
wiki_url=https://github.com/devorgpl/compost/wiki
check=false
[ "${1:-}" = --check ] && check=true

cargo build --quiet
bin=target/debug/compost
# Help shows the current value of variables it reads, so they must be unset.
unset COMPOST_SERVER COMPOST_HOME

# commands ARGS...: the subcommands listed under "Commands:" in the help of ARGS.
commands() {
    "$bin" "$@" --help | awk '
        /^Commands:/ { on = 1; next }
        on && /^$/ { exit }
        on && /^  [a-z]/ && $1 != "help" { print $1 }'
}

# section ARGS...: the help of the command, then of each subcommand.
section() {
    printf '\n## `compost%s`\n\n```text\n' "$(printf ' %s' "$@")"
    "$bin" "$@" --help
    printf '```\n'
    for sub in $(commands "$@"); do
        section "$@" "$sub"
    done
}

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
generated=$tmp/CLI-Reference.md
{
    printf '# CLI reference\n\n'
    printf '<!-- Generated by scripts/docs.sh from the help texts in src/cli; run `just docs` instead of editing. -->\n\n'
    printf 'The `--help` of every command. Guides: [Applications](Applications.md), [Servers and shared apps](Servers-and-Shared-Apps.md), [Backup and restore](Backup-and-Restore.md).\n\n'
    printf 'Exit codes: `0` OK · `1` unexpected error · `2` invalid local config or usage · `3` server not ready or a server-side check failed · `4` deployed, but not healthy · `130` interrupted with Ctrl-C.\n\n'
    printf '## `compost`\n\n```text\n'
    "$bin" --help
    printf '```\n'
    for sub in $(commands); do
        section "$sub"
    done
} >"$generated"
images=$tmp/Bundled-Images.md
{
    printf '# Bundled images

'
    printf '<!-- Generated by scripts/docs.sh from `compost images --markdown`; run `just docs` instead of editing. -->

'
    printf 'The images and modules compost uses for each shared app type unless `compost-server.yaml` names others, as of the release this wiki shows. `compost images` prints them for the compost you have installed, `compost server images` what runs on a server.

'
    printf -- '- A **moving tag** (`caddy:2-alpine`, `postgres:18`) points to newer images as they are published: `server deploy --apply --pull` fetches them.
'
    printf -- '- An **exact tag** and a **pinned** Go module change only with a compost release; compare this page between releases to see what an upgrade changes.
'
    printf -- '- A **built** image is built on the server from its build bases.

'
    printf 'The Note column says when an image is used and which key replaces it.

'
    "$bin" images --markdown
} >"$images"

# wiki_pages: the pages for agents, with the generated CLI reference: Home.md,
# then in the order of _Sidebar.md, then the rest. One path per line.
wiki_pages() {
    {
        echo Home.md
        grep -o ']([A-Za-z0-9_-]*\.md)' "$pages/_Sidebar.md" | sed 's/^](\(.*\))$/\1/'
        for page in "$pages"/*.md; do basename "$page"; done
    } | awk '$0 != "_Sidebar.md" && !seen[$0]++' |
        while read -r name; do
            case "$name" in
            CLI-Reference.md) echo "$generated" ;;
            Bundled-Images.md) echo "$images" ;;
            *) echo "$pages/$name" ;;
            esac
        done
}

mkdir -p "$tmp/agents/references"
for page in $(wiki_pages); do
    cp "$page" "$tmp/agents/references/$(basename "$page")"
done
{
    # Page links: `](Some-Page.md#part)` → `](<wiki>/Some-Page#part)`, as publish-wiki.sh makes them.
    sed -E "s|\]\(([A-Za-z0-9_-]+)\.md(#[^)]*)?\)|]($wiki_url/\1\2)|g" "$agents/llms-index.md"
    printf '\n## Optional\n\n'
    printf -- '- [llms-full.txt](https://raw.githubusercontent.com/devorgpl/compost/master/docs/agents/llms-full.txt): all pages above in one file (master; every release also has its own)\n'
} >"$tmp/agents/llms.txt"
{
    printf '# compost documentation\n\n'
    printf '<!-- Generated by scripts/docs.sh from docs/wiki; run `just docs` instead of editing. -->\n\n'
    printf 'Every page of the compost user documentation, separated by `---`. A link to `Page.md` means the page of that name in this file.\n'
    for page in $(wiki_pages); do
        printf '\n---\n\n<!-- %s -->\n\n' "$(basename "$page")"
        cat "$page"
    done
} >"$tmp/agents/llms-full.txt"

if ! $check; then
    cp "$generated" "$out"
    cp "$images" "$images_out"
    cp "$tmp/agents/llms.txt" "$tmp/agents/llms-full.txt" "$agents/"
    # Only when changed: build.rs embeds this folder, so touching it rebuilds compost.
    if ! diff -r -q "$references" "$tmp/agents/references" >/dev/null 2>&1; then
        rm -rf "$references"
        cp -R "$tmp/agents/references" "$references"
    fi
    echo "Wrote $out, $images_out, $agents/llms.txt, $agents/llms-full.txt and $references"
    exit 0
fi

failed=false
if ! diff -u "$out" "$generated"; then
    echo "$out is out of date: run \`just docs\`" >&2
    failed=true
fi
if ! diff -u "$images_out" "$images"; then
    echo "$images_out is out of date: run \`just docs\`" >&2
    failed=true
fi
for file in llms.txt llms-full.txt; do
    if ! diff -u "$agents/$file" "$tmp/agents/$file"; then
        echo "$agents/$file is out of date: run \`just docs\`" >&2
        failed=true
    fi
done
if ! diff -r "$references" "$tmp/agents/references"; then
    echo "$references is out of date: run \`just docs\`" >&2
    failed=true
fi

# Every page is listed in llms-index.md.
for page in "$pages"/*.md; do
    name="$(basename "$page")"
    [ "$name" = _Sidebar.md ] && continue
    if ! grep -q "]($name)" "$agents/llms-index.md"; then
        echo "$agents/llms-index.md: $name is not listed" >&2
        failed=true
    fi
done

# anchors PAGE: the anchors of its headings, as GitHub makes them:
# lowercase, punctuation dropped, spaces to `-`. Code blocks are skipped.
anchors() {
    awk '/^```/ { code = !code; next } !code && /^#+ / { sub(/^#+ /, ""); print }' "$1" |
        tr 'A-Z' 'a-z' | sed -e 's/[^a-z0-9 _-]//g' -e 's/ /-/g'
}

# Links to pages (`Page.md`, `Page.md#part`) and within a page (`#part`);
# in SKILL.md, to `references/Page.md`.
skill=$agents/skills/compost/SKILL.md
for page in "$pages"/*.md "$agents/llms-index.md" "$skill"; do
    grep -o '](\(references/\)\{0,1\}\([A-Za-z0-9_-]*\.md\)\{0,1\}\(#[^)]*\)\{0,1\})' "$page" | sed 's/^](\(.*\))$/\1/' |
        while read -r link; do
            if [ "$page" = "$skill" ]; then
                case "$link" in
                references/*) link="${link#references/}" ;;
                '#'*) ;;
                *)
                    echo "$page: link to a page outside references/: $link" >&2
                    echo x
                    continue
                    ;;
                esac
            fi
            target="${link%%#*}"
            anchor=""
            case "$link" in *'#'*) anchor="${link#*#}" ;; esac
            if [ -n "$target" ]; then file="$pages/$target"; else file="$page"; fi
            if [ ! -f "$file" ]; then
                echo "$page: link to missing page $link" >&2
                echo x
            elif [ -n "$anchor" ] && ! anchors "$file" | grep -qx -- "$anchor"; then
                echo "$page: link to missing heading $link" >&2
                echo x
            fi
        done
done | grep x >/dev/null && failed=true  # not -q: it would stop the loop at the first error

if $failed; then
    exit 1
fi
echo "$pages and $agents are up to date"
